import * as C from './core.js';
import {whatsappLink} from './referrals.js';

export function ensureDemoAdmin(state){
 if(state.serverAuthoritative)return;state.profile.id ||= 'demo-self';state.deposits ||= [];state.withdrawals ||= [];state.reservedLC ||= 0;state.adminAudit ||= [];
 if(!state.adminAccounts)state.adminAccounts=state.affiliates.map((a,index)=>({
  profile:{id:a.id,name:a.name,email:`piloto.${index+1}@example.test`,whatsapp:a.whatsapp||'',referralCode:'EXEMPLO-'+(index+1),role:'user',status:'active',referrerId:index?state.affiliates[index-1].id:state.profile.id},
  balances:{LC:7000+index*800,RC:14000+index*900},reservedLC:0,withdrawnCents:0,transactions:[],inventory:[],
  robots:(a.acquisitions||[{catalogId:a.robotId||'moss'}]).map((r,i)=>{const def=state.catalog.find(c=>c.id===r.catalogId)||state.catalog[0],createdAt=Date.now()-(i+1)*C.DAY;return {uid:'example-'+a.id+'-'+i,catalogId:def.id,level:r.level||1,createdAt,lastCollected:Date.now(),earned:0,used:0,equipment:[],contract:C.acquisitionContract(state,def,createdAt)};})
 }));
}
export function demoAccount(state,id){if(id===state.profile.id||id==='demo-self')return state;const account=(state.serverAuthoritative?state.adminUsers:state.adminAccounts)?.find(a=>a.profile.id===id);if(!account)throw new Error('Piloto não encontrado.');return {...account,settings:state.settings,catalog:state.catalog,parts:state.parts,serverAuthoritative:false};}
export function adminAudit(state,action,userId,before,after,reason){state.adminAudit ||= [];state.adminAudit.unshift({id:C.uuid(),action,userId,actorId:state.profile.id,reason,before:C.clone(before),after:C.clone(after),at:Date.now()});}
function requireDemo(state){if(state.serverAuthoritative)throw new Error('Esta operação precisa ser autorizada e executada pelo servidor.');}
function reasonText(value){const reason=String(value||'').trim();if(reason.length<3||reason.length>300)throw new Error('Informe um motivo de 3 a 300 caracteres.');return reason;}
export function adjustDemoBalance(state,id,currency,amount,reason){requireDemo(state);ensureDemoAdmin(state);reason=reasonText(reason);if(!['LC','RC'].includes(currency)||!Number.isSafeInteger(amount)||!amount)throw new Error('Informe um ajuste inteiro diferente de zero.');const account=demoAccount(state,id),before=C.clone(account.balances);C.transaction(account,'Ajuste administrativo · '+reason,currency,amount);adminAudit(state,'balance_adjustment',id,before,account.balances,reason);return account.balances;}
export function updateDemoRobot(state,id,uid,values,reason){requireDemo(state);reason=reasonText(reason);const account=demoAccount(state,id),robot=account.robots.find(r=>r.uid===uid);if(!robot)throw new Error('Robô não encontrado.');
 for(const key of ['daily','attack','defense','health'])if(!Number.isSafeInteger(values[key])||values[key]<(key==='defense'?0:1)||values[key]>10000000)throw new Error('Atributos devem ser inteiros dentro dos limites do formulário.');
 const before=C.clone(robot);C.collect(account,uid);robot.overrides={...robot.overrides,...values};adminAudit(state,'robot_attributes',id,before,robot,reason);return robot;
}
export function resolveDemoWithdrawal(state,id,approve,reason){requireDemo(state);ensureDemoAdmin(state);reason=reasonText(reason);const request=state.withdrawals.find(w=>w.id===id);if(!request||request.status!=='pending')throw new Error('Este saque não está pendente de aprovação.');
 const account=demoAccount(state,request.userId),before=C.clone(request);if((account.reservedLC||0)<request.debitLC)throw new Error('Reserva de LC inconsistente.');
 if(!approve)C.transaction(account,'Saque recusado · devolução da reserva','LC',request.debitLC);
 account.reservedLC-=request.debitLC;account.withdrawnCents=(account.withdrawnCents||0)+(approve?request.requestedCents:0);
 // Contas de exemplo usam um wrapper: sincroniza propriedades escalares.
 if(account!==state){const stored=state.adminAccounts.find(a=>a.profile.id===request.userId);stored.reservedLC=account.reservedLC;stored.withdrawnCents=account.withdrawnCents;}
 request.status=approve?'paid':'cancelled';request.reviewedAt=Date.now();request.reviewedBy=state.profile.id;request.reviewReason=reason;request.simulated=true;
 adminAudit(state,approve?'withdrawal_approved':'withdrawal_rejected',request.userId,before,request,reason);return request;
}
export function deleteDemoUser(state,id){requireDemo(state);ensureDemoAdmin(state);if(!id||id===state.profile.id)throw new Error('Piloto inválido.');const account=(state.adminAccounts||[]).find(a=>a.profile.id===id);if(!account)throw new Error('Piloto não encontrado.');if(account.profile.role==='admin')throw new Error('Não é possível excluir um administrador.');const before={name:account.profile.name,balances:account.balances,robots:(account.robots||[]).length};
 state.adminAccounts=state.adminAccounts.filter(a=>a.profile.id!==id);const social=state.social||{};social.queue=(social.queue||[]).filter(q=>q.userId!==id);for(const l of social.listings||[])if(l.sellerId===id&&['open','proposal'].includes(l.status))l.status='cancelled';for(const g of social.guilds||[]){g.members=(g.members||[]).filter(m=>m.userId!==id);if(g.founderId===id)g.founderId=g.members[0]?.userId||null;}social.guilds=(social.guilds||[]).filter(g=>g.members?.length);
 adminAudit(state,'user_delete',id,before,null,'Exclusão pelo painel');return before;}
export function paged(items,page=1,size=8){const pages=Math.max(1,Math.ceil(items.length/size)),current=Math.min(pages,Math.max(1,Number(page)||1));return {items:items.slice((current-1)*size,current*size),page:current,pages,total:items.length};}

export function createAdminOperations(env){const {escape:esc,icon:I,button:btn,input,textarea,coin,sprite,format:n,brl,modal}=env;const pages={users:1,deposits:1,withdrawals:1,audit:1};let userSearch='',paymentFilter='all';
 const self=()=>env.getState().profile.id||'demo-self';
 const all=()=>{const s=env.getState();if(env.isDemo)ensureDemoAdmin(s);return env.isDemo?[s,...s.adminAccounts]:s.adminUsers||[];};
 const name=id=>all().find(a=>a.profile.id===id)?.profile.name||'Piloto';
 const date=value=>value?new Date(value).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—';
 function pagination(tab,data){return `<div class="admin-pagination"><span>${data.total} registros · Página ${data.page}/${data.pages}</span><div>${btn('Anterior','admin-page',`data-tab="${tab}" data-id="${data.page-1}" ${data.page===1?'disabled':''}`,'secondary')}${btn('Próxima','admin-page',`data-tab="${tab}" data-id="${data.page+1}" ${data.page===data.pages?'disabled':''}`,'secondary')}</div></div>`;}
 function users(){const records=all().filter(a=>[a.profile.name,a.profile.email,a.profile.whatsapp,a.profile.referralCode].join(' ').toLowerCase().includes(userSearch.toLowerCase())),data=paged(records,pages.users);
  return `<div class="section-title"><h2>Pilotos cadastrados ${env.isDemo?'(teste)':''}</h2><span>${records.length} perfis</span></div><form id="admin-user-search" class="admin-search">${input('Buscar por nome, e-mail, WhatsApp ou código','query',userSearch,'search')}<button class="btn secondary" type="submit">${I('users')} Buscar</button></form><div class="admin-user-list">${data.items.map(a=>{const model=env.getState().catalog.find(r=>r.id===a.robots?.[0]?.catalogId)||env.getState().catalog[0];return `<article><div class="admin-pilot-avatar">${sprite(model)}</div><div><span class="eyebrow">${esc(a.profile.role||'user')} · ${esc(a.profile.status||'active')}</span><h3>${esc(a.profile.name)}</h3><p>${esc(a.profile.email||'E-mail não informado')}</p><small>WhatsApp: ${esc(a.profile.whatsapp||'não cadastrado')} · ${a.robots?.length||0} robôs</small></div><div class="admin-user-balances"><span>${coin('LC')} ${n(a.balances?.LC)} LC</span><span>${coin('RC')} ${n(a.balances?.RC)} RC</span><small>${n(a.reservedLC||0)} LC reservadas</small></div>${btn('Abrir perfil '+I('arrow'),'admin-user',`data-id="${esc(a.profile.id)}"`,'secondary')}</article>`;}).join('')||'<div class="empty">Nenhum piloto encontrado.</div>'}</div>${pagination('users',data)}<div class="section-title"><h2>Histórico de ajustes</h2></div>${audit()}`;
 }
 function audit(){const data=paged(env.getState().adminAudit||[],pages.audit);return `<div class="table-wrap"><table><thead><tr><th>Ação / piloto</th><th>Motivo</th><th>Data</th></tr></thead><tbody>${data.items.map(a=>`<tr><td>${esc(a.action)}<small class="cell-sub">${esc(name(a.userId))}</small></td><td>${esc(a.reason)}</td><td>${date(a.at)}</td></tr>`).join('')||'<tr><td colspan="3">Nenhum ajuste administrativo registrado.</td></tr>'}</tbody></table></div>${pagination('audit',data)}`;}
 function payments(tab){const s=env.getState(),withdrawal=tab==='withdrawals',records=(withdrawal?s.withdrawals:s.deposits)||[],filtered=records.filter(p=>paymentFilter==='all'||p.status===paymentFilter),data=paged(filtered,pages[tab]),pending=records.filter(p=>p.status==='pending').length;
  return `${withdrawal?`<form id="admin-withdrawal-policy" class="admin-form"><section><h3>${I('wallet')} Aprovação e processamento</h3>${!env.isDemo?`<label class="checkbox"><input type="checkbox" name="paymentsEnabled" ${s.settings.realMoneyEnabled?'checked':''}> Ativar depósitos e novas solicitações de saque</label>`:''}<div class="notice">${I('info')} ${env.isDemo?'Processamento demonstrativo: nenhuma transferência bancária é realizada.':'O servidor verifica reservas e a resposta do gateway antes de concluir uma transferência.'}</div><label class="checkbox"><input type="checkbox" name="autoWithdrawals" ${s.settings.autoWithdrawals?'checked':''}> Processar novos saques automaticamente</label><div class="form-grid">${input('Limite automático por saque em R$ (0 = sem limite)','autoWithdrawalMax',s.settings.autoWithdrawalMax??50,'number','min="0" step="0.01" required')}${input('Valor mínimo (R$)','minWithdraw',s.settings.minWithdraw,'number','min="0.01" step="0.01" required')}${input('Taxa de saque (%)','withdrawFee',s.settings.withdrawFee,'number','min="0" max="100" step="0.01" required')}</div><p>Pedidos que ultrapassam o limite ficam pendentes. A cotação e a taxa de um pedido já criado permanecem registradas.</p><button class="btn primary" type="submit">Salvar regras de aprovação</button></section></form>`:''}<div class="admin-payment-overview"><article><small>${withdrawal?'PEDIDOS DE SAQUE':'DEPÓSITOS REGISTRADOS'}</small><b>${records.length}</b></article><article><small>VALOR TOTAL</small><b>${brl(records.reduce((sum,p)=>sum+(p.requestedCents??p.amountCents??0),0)/100)}</b></article><article><small>${withdrawal?'TAXAS DOS PEDIDOS':'PENDENTES'}</small><b>${withdrawal?brl(records.reduce((sum,p)=>sum+(p.feeCents||0),0)/100):pending}</b></article><article><small>AGUARDANDO</small><b>${pending}</b></article></div><div class="section-title"><h2>${withdrawal?'Saques e reservas':'Depósitos e confirmações'}</h2></div><div class="tabs admin-payment-filters">${['all','pending',withdrawal?'paid':'confirmed',withdrawal?'cancelled':'failed'].map(value=>`<button data-a="admin-payment-filter" data-id="${value}" class="${value===paymentFilter?'active':''}">${{all:'Todos',pending:'Pendentes',paid:'Concluídos',confirmed:'Confirmados',cancelled:'Recusados',failed:'Falhos'}[value]}</button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Piloto / referência</th><th>Valor e moedas</th><th>Taxa / status</th><th>Data</th>${withdrawal?'<th>Revisão</th>':''}</tr></thead><tbody>${data.items.map(p=>`<tr><td>${esc(name(p.userId))}<small class="cell-sub">${esc(p.id)}</small></td><td><b>${brl((p.requestedCents??p.amountCents)/100)}</b><small class="cell-sub">${withdrawal?n(p.debitLC)+' LC reservadas':n(p.LC)+' LC creditadas'}</small></td><td><span class="status ${['paid','confirmed'].includes(p.status)?'good':''}">${esc({paid:env.isDemo?'Pago (simulado)':'Pago',confirmed:'Confirmado',pending:'Pendente',cancelled:'Recusado',failed:'Falho'}[p.status]||p.status)}</span><small class="cell-sub">Taxa: ${brl((p.feeCents||0)/100)}</small></td><td>${date(p.createdAt)}</td>${withdrawal?`<td>${p.status==='pending'&&(env.isDemo||p.providerStatus==='review')?`${btn('Aprovar','admin-withdrawal-review',`data-id="${esc(p.id)}" data-approve="true"`,'secondary')}${btn('Recusar','admin-withdrawal-review',`data-id="${esc(p.id)}" data-approve="false"`,'text')}`:esc(p.autoApproved?'Automático':p.reviewReason||'Concluído')}</td>`:''}</tr>`).join('')||`<tr><td colspan="${withdrawal?5:4}">Nenhuma operação neste filtro. ${env.isDemo?'Faça uma operação de teste pela carteira.':''}</td></tr>`}</tbody></table></div>${pagination(tab,data)}`;
 }
 function openUser(id){const s=env.getState(),account=env.isDemo?demoAccount(s,id):all().find(a=>a.profile.id===id);if(!account)return;const contact=whatsappLink(account.profile.whatsapp),children=all().filter(a=>a.profile.referrerId===id),robots=account.robots||[];
  modal(`<span class="eyebrow">PERFIL DO PILOTO ${env.isDemo?'· DEMONSTRAÇÃO':''}</span><h2 id="modal-title">${esc(account.profile.name)}</h2><div class="admin-profile-info"><span>E-mail <b>${esc(account.profile.email||'Não informado')}</b></span><span>WhatsApp <b>${esc(account.profile.whatsapp||'Não cadastrado')}</b></span><span>Código <b>${esc(account.profile.referralCode||'—')}</b></span><span>Indicação <b>${esc(account.profile.referrerId?name(account.profile.referrerId):account.profile.referredByCode||'Sem indicador')}</b></span>${contact?`<a class="btn secondary" href="${contact}" target="_blank" rel="noopener noreferrer">Abrir WhatsApp</a>`:''}</div><div class="admin-user-balances profile-balances"><span>${coin('LC')} ${n(account.balances.LC)} LC</span><span>${coin('RC')} ${n(account.balances.RC)} RC</span><small>${n(account.reservedLC||0)} LC reservadas</small>${btn('Ajustar saldo','admin-balance',`data-id="${esc(id)}"`,'secondary')}</div><div class="section-title"><h3>Robôs adquiridos (${robots.length})</h3></div><div class="admin-owned-robots">${robots.map(r=>{const info=C.robotInfo({...account,settings:s.settings,catalog:s.catalog,parts:s.parts},r);return `<article>${sprite(info)}<div><h3>${esc(info.name)} <small>NV. ${info.level}</small></h3><p>${n(info.daily)} RC/dia · ${info.active?'Ativo':'Expirado'} · ${r.equipment.length} peças</p><small>${info.attack} ataque · ${info.defense} defesa · ${info.health} vida</small><small>Adquirido: ${date(r.createdAt)} · Expira: ${date(info.expires)}</small><small>${n(info.used)} batalhas realizadas · ${n(info.remainingBattles)} restantes</small><small>${n(info.earned)} RC produzidas · ${n(info.principalReturnLC)} LC de devolução</small></div>${btn('Atributos / produção','admin-owned-robot',`data-user="${esc(id)}" data-id="${esc(r.uid)}"`,'secondary')}</article>`;}).join('')||'<p>Nenhum robô adquirido.</p>'}</div><div class="section-title"><h3>Equipamentos (${account.inventory?.length||0})</h3></div><div class="admin-owned-parts">${(account.inventory||[]).map(item=>{const p=s.parts.find(p=>p.id===item.partId);return `<article>${env.partArt(p)}<div><b>${esc(p?.name)}</b><small>NV. ${item.level} · ${item.equippedOn?'Equipado em '+esc(robots.find(r=>r.uid===item.equippedOn)?.catalogId||'robô'):'No inventário'}</small></div></article>`;}).join('')||'<p class="subtle">Nenhuma peça adquirida.</p>'}</div><div class="section-title"><h3>Equipe direta (${children.length})</h3></div><div class="admin-team-links">${children.map(child=>btn(esc(child.profile.name)+' · '+n(child.balances.LC)+' LC','admin-user',`data-id="${esc(child.profile.id)}"`,'secondary')).join('')||'<p class="subtle">Nenhum convite direto.</p>'}</div><div class="modal-actions">${btn('Depósitos','admin-open-tab','data-id="deposits"','secondary')}${btn('Saques','admin-open-tab','data-id="withdrawals"','secondary')}${account.profile.role==='admin'?'':btn('Excluir piloto','admin-user-delete',`data-id="${esc(id)}"`,'danger')}${btn('Voltar','close','','secondary')}</div>`,'admin-user-modal large');
 }
 function balance(id){const a=env.isDemo?demoAccount(env.getState(),id):all().find(a=>a.profile.id===id);modal(`<h2 id="modal-title">Ajustar saldo de ${esc(a.profile.name)}</h2><form id="admin-balance-form" data-id="${esc(id)}"><label class="form-field"><span>Moeda</span><select name="currency"><option>LC</option><option>RC</option></select></label>${input('Quantidade (positiva para adicionar, negativa para remover)','amount',100,'number','step="1" required')}${textarea('Motivo do ajuste','reason','')}<p>Saldo disponível: ${n(a.balances.LC)} LC · ${n(a.balances.RC)} RC. Reservas de saques permanecem separadas.</p><button class="btn primary wide" type="submit">Registrar ajuste ${env.isDemo?'de teste':''}</button></form>`);}
 function ownedRobot(id,uid){const s=env.getState(),a=env.isDemo?demoAccount(s,id):{...all().find(a=>a.profile.id===id),settings:s.settings,catalog:s.catalog,parts:s.parts,serverAuthoritative:true},r=a.robots.find(r=>r.uid===uid),info=C.robotInfo(a,r);modal(`${sprite(info)}<h2 id="modal-title">Atributos de ${esc(info.name)}</h2><form id="admin-owned-robot-form" data-id="${esc(uid)}" data-user="${esc(id)}"><div class="form-grid">${['daily','attack','defense','health'].map(key=>input({daily:'Produção efetiva RC/dia',attack:'Ataque efetivo',defense:'Defesa efetiva',health:'Vida efetiva'}[key],key,info[key],'number',`min="${key==='defense'?0:1}" max="10000000" step="1" required`)).join('')}</div>${textarea('Motivo da alteração','reason','')}<p>A produção acumulada é liquidada na taxa anterior antes de salvar a nova. O contrato de aquisição e sua devolução permanecem registrados.</p><button class="btn primary wide" type="submit">Salvar atributos</button></form>`,'large');}
 function deleteUser(id){const s=env.getState(),account=env.isDemo?demoAccount(s,id):all().find(a=>a.profile.id===id);if(!account||account.profile.role==='admin')return;modal(`<span class="eyebrow" style="color:var(--danger)">EXCLUSÃO DEFINITIVA</span><h2 id="modal-title">Excluir ${esc(account.profile.name)}?</h2><p>A conta, os robôs, os saldos e o acesso do piloto serão removidos pelo servidor. Convidados diretos ficam sem indicador e o histórico financeiro auditável é preservado no registro administrativo. Digite <b>${esc(account.profile.name)}</b> para confirmar.</p><form id="admin-user-delete-form" data-id="${esc(id)}" data-name="${esc(account.profile.name)}">${input('Nome do piloto','confirm','','text','autocomplete="off" required')}${textarea('Motivo (opcional)','reason','')}<button class="btn danger wide" type="submit">Excluir piloto permanentemente</button></form>`);}
 function review(id,approve){const r=env.getState().withdrawals.find(w=>w.id===id);if(!r)return;modal(`<span class="eyebrow">REVISÃO DE SAQUE ${env.isDemo?'· SIMULADO':''}</span><h2 id="modal-title">${approve?'Aprovar':'Recusar'} ${brl(r.requestedCents/100)}</h2><p>${esc(name(r.userId))} · Taxa ${brl(r.feeCents/100)} · Reserva ${n(r.debitLC)} LC</p><form id="admin-withdrawal-review-form" data-id="${esc(id)}" data-approve="${approve}">${textarea('Motivo / observação','reason',approve?'Aprovado no painel':'Recusado no painel')}<button class="btn primary wide" type="submit">${approve?env.isDemo?'Aprovar e concluir simulação':'Aprovar saque':'Recusar e liberar reserva'}</button></form>`);}
 function notices(){const s=env.getState().settings;return `<form id="admin-notice-form" class="admin-form"><section><h3>${I('bell')} Aviso para todos os pilotos</h3><p>Personalize a mensagem, imagem e botão. O aviso aparece no sino do jogo; o destaque pode abrir a mensagem ao entrar.</p><div class="form-grid">${input('Título','announcement',s.announcement,'text','maxlength="120" required')}${input('Texto do botão','announcementButton',s.announcementButton,'text','maxlength="60"')}${input('Link do botão','announcementLink',s.announcementLink)}${input('URL da imagem (opcional)','announcementImage',s.announcementImage,'url')}</div>${textarea('Mensagem','announcementBody',s.announcementBody)}<label class="checkbox"><input name="announcementActive" type="checkbox" ${s.announcementActive!==false?'checked':''}> Aviso ativo para todos</label><label class="checkbox"><input name="announcementPopup" type="checkbox" ${s.announcementPopup?'checked':''}> Exibir ao entrar no jogo</label><div class="notice">${I('info')} ${env.isDemo?'Publicação local de teste. O envio aos usuários cadastrados será conectado ao backend.':'O aviso será publicado pelo servidor para os usuários.'}</div><button class="btn primary" type="submit">${I('bell')} Publicar aviso ${env.isDemo?'de teste':'global'}</button></section></form>`;}
 async function submit(f,v){const s=env.getState();if(f.id==='admin-notice-form'){const next={...s.settings,...v,announcementActive:v.announcementActive==='on',announcementPopup:v.announcementPopup==='on',announcementVersion:(s.settings.announcementVersion||0)+1};C.validateSettings(next);await env.mutate(state=>{const before=state.settings;state.settings=next;adminAudit(state,'global_notice',self(),before,next,'Aviso publicado no painel');},'Aviso publicado.',{action:'admin_publish_notice',payload:{notice:next,idempotency_key:C.uuid()}});return true;}
  if(f.id==='admin-user-search'){userSearch=v.query||'';pages.users=1;env.render();return true;}
  if(f.id==='admin-balance-form')await env.mutate(state=>adjustDemoBalance(state,f.dataset.id,v.currency,Number(v.amount),v.reason),'Ajuste registrado.',{action:'admin_adjust_balance',payload:{user_id:f.dataset.id,currency:v.currency,amount:Number(v.amount),reason:v.reason,idempotency_key:C.uuid()}});
  else if(f.id==='admin-owned-robot-form'){const values=Object.fromEntries(['daily','attack','defense','health'].map(k=>[k,Number(v[k])]));await env.mutate(state=>updateDemoRobot(state,f.dataset.user,f.dataset.id,values,v.reason),'Atributos atualizados.',{action:'admin_update_robot',payload:{user_id:f.dataset.user,robot_id:f.dataset.id,values,reason:v.reason,idempotency_key:C.uuid()}});}
  else if(f.id==='admin-user-delete-form'){if(String(v.confirm||'').trim()!==f.dataset.name)throw new Error('Digite o nome do piloto exatamente como exibido.');await env.mutate(state=>deleteDemoUser(state,f.dataset.id),'Piloto excluído.',{action:'admin_delete_user',payload:{user_id:f.dataset.id,reason:v.reason,idempotency_key:C.uuid()}});}
  else if(f.id==='admin-withdrawal-review-form')await env.mutate(state=>resolveDemoWithdrawal(state,f.dataset.id,f.dataset.approve==='true',v.reason),'Revisão registrada.',{action:'admin_review_withdrawal',payload:{withdrawal_id:f.dataset.id,approve:f.dataset.approve==='true',reason:v.reason,idempotency_key:C.uuid()}});
  else if(f.id==='admin-withdrawal-policy'){if(!env.isDemo&&!await env.mutate(()=>{},'Política de pagamentos salva.',{action:'admin_payments_policy',payload:{enabled:v.paymentsEnabled==='on'}}))return true;const next={...env.getState().settings,autoWithdrawals:v.autoWithdrawals==='on',autoWithdrawalMax:Number(v.autoWithdrawalMax),minWithdraw:Number(v.minWithdraw),withdrawFee:Number(v.withdrawFee)};C.validateSettings(next);await env.mutate(state=>{const before=state.settings;state.settings=next;adminAudit(state,'withdrawal_policy',self(),before,next,'Regras de aprovação atualizadas');},'Política de saques salva.',{action:'admin_save',payload:{settings:next}});}
  else return false;return true;
 }
 return {render:tab=>!env.isDemo&&!env.getState().adminUsers?'<div class="notice">Não foi possível carregar os dados administrativos. Atualize a página e confira sua sessão.</div>':tab==='users'?users():tab==='notices'?notices():payments(tab),handles:tab=>['users','deposits','withdrawals','notices'].includes(tab),openUser,balance,ownedRobot,review,deleteUser,submit,page:(tab,page)=>{if(Object.hasOwn(pages,tab))pages[tab]=Number(page);},filter:value=>{paymentFilter=value;pages.deposits=pages.withdrawals=1;}};
}
